class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
n = int(input())
s = 0
p = [Point(0, 0)]
for i in range(n):
    a, b = map(int, input().split())
    p.append(Point(a, b))

p.append(Point(0, 0))
p.sort(key=lambda a: (a.x, a.y))

for i in range(1, n + 1):
    tmp = 1000
    if p[i - 1].y == p[i].y:
        tmp = p[i].x - p[i - 1].x
    if p[i].y == p[i + 1].y:
        tmp = min(tmp, p[i + 1].x - p[i].x)
    s += 0 if tmp == 1000 else tmp
print(s)
